mapper.select:
SELECT num, ucode,uwriter,ucontent,reip,bcdate, row_num FROM (
SELECT num, ucode,uwriter,ucontent,reip,bcdate, ROW_NUMBER() 
OVER(ORDER BY ucode desc) AS row_num FROM BOARD_skin_comm where ucode=#{num}
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE BOARD 
SET comm_count = comm_count + 1 
WHERE num = #{num}

UPDATE BOARD 
SET comm_count = comm_count - 1 
WHERE num = #{num}
